{"file_path":"src/parser.js","content":"/**
 * Parser for the configuration document format described in the task
 * specification. `parseDocument` turns the raw text into a tree of plain
 * tagged nodes (see the `kind` field of each node) that `src/format.js` can
 * render as JSON or as a flat key listing.
 *
 * Node shapes:
 *   { kind: 'table', map: Map<string, Node>, headerDefined: boolean }
 *   { kind: 'aot', tables: Node[] }               // array of tables
 *   { kind: 'array', items: Node[] }
 *   { kind: 'string' | 'integer' | 'float' | 'boolean', value }
 */

export class ConfError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

const NAME_CHAR = /[A-Za-z0-9_-]/
const INTEGER_RE = /^[+-]?\d+(?:_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(?:_\d+)*(?:(?:\.\d+(?:_\d+)*)(?:[eE][+-]?\d+(?:_\d+)*)?|(?:[eE][+-]?\d+(?:_\d+)*))$/

function makeTable() {
  return { kind: 'table', map: new Map(), headerDefined: false }
}

function formatPath(parts) {
  let out = ''
  for (const p of parts) {
    if (typeof p === 'number') out += `[${p}]`
    else out += (out.length ? '.' : '') + p
  }
  return out
}

class LineScanner {
  constructor(line, lineNo) {
    this.s = line
    this.i = 0
    this.n = line.length
    this.lineNo = lineNo
  }

  peek() {
    return this.i < this.n ? this.s[this.i] : undefined
  }

  err(reason) {
    throw new ConfError(this.lineNo, reason)
  }

  skipWS() {
    while (this.i < this.n && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  atEnd() {
    return this.i >= this.n || this.s[this.i] === '#' || this.s[this.i] === ';'
  }
}

function parseBasicString(sc) {
  sc.i++ // consume opening quote
  let out = ''
  while (true) {
    if (sc.i >= sc.n) sc.err('unterminated string')
    const c = sc.s[sc.i]
    if (c === '"') {
      sc.i++
      return out
    }
    if (c === '\\') {
      sc.i++
      if (sc.i >= sc.n) sc.err('unterminated string')
      const e = sc.s[sc.i]
      switch (e) {
        case '"': out += '"'; sc.i++; break
        case '\\': out += '\\'; sc.i++; break
        case 'n': out += '\n'; sc.i++; break
        case 't': out += '\t'; sc.i++; break
        case 'r': out += '\r'; sc.i++; break
        case '0': out += '\0'; sc.i++; break
        case 'u': {
          sc.i++
          const hex = sc.s.slice(sc.i, sc.i + 4)
          if (hex.length < 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) sc.err('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          sc.i += 4
          break
        }
        default:
          sc.err(`invalid escape \\${e}`)
      }
    } else {
      out += c
      sc.i++
    }
  }
}

function parseLiteralString(sc) {
  sc.i++ // consume opening quote
  const start = sc.i
  while (true) {
    if (sc.i >= sc.n) sc.err('unterminated string')
    if (sc.s[sc.i] === "'") {
      const out = sc.s.slice(start, sc.i)
      sc.i++
      return out
    }
    sc.i++
  }
}

function parseName(sc) {
  const c = sc.peek()
  if (c === '"') return parseBasicString(sc)
  if (c === "'") return parseLiteralString(sc)
  if (c !== undefined && NAME_CHAR.test(c)) {
    const start = sc.i
    while (sc.i < sc.n && NAME_CHAR.test(sc.s[sc.i])) sc.i++
    return sc.s.slice(start, sc.i)
  }
  sc.err('expected a name')
}

function parseDottedName(sc) {
  const parts = []
  while (true) {
    sc.skipWS()
    parts.push(parseName(sc))
    sc.skipWS()
    if (sc.peek() === '.') {
      sc.i++
      continue
    }
    break
  }
  return parts
}

function parseValue(sc, prefixPath) {
  sc.skipWS()
  if (sc.atEnd()) sc.err('expected a value')
  const c = sc.s[sc.i]
  if (c === ',' || c === ']' || c === '}') sc.err('expected a value')
  if (c === '"') return { kind: 'string', value: parseBasicString(sc) }
  if (c === "'") return { kind: 'string', value: parseLiteralString(sc) }
  if (c === '[') return parseArray(sc, prefixPath)
  if (c === '{') return parseInlineTable(sc, prefixPath)

  const start = sc.i
  while (sc.i < sc.n && ![' ', '\t', ',', ']', '}'].includes(sc.s[sc.i])) sc.i++
  const token = sc.s.slice(start, sc.i)
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  if (INTEGER_RE.test(token)) return { kind: 'integer', value: parseInt(token.replace(/_/g, ''), 10) }
  if (FLOAT_RE.test(token)) return { kind: 'float', value: parseFloat(token.replace(/_/g, '')) }
  sc.err(`invalid value ${token}`)
}

function parseArray(sc, prefixPath) {
  sc.i++ // consume [
  const items = []
  sc.skipWS()
  if (sc.peek() === ']') {
    sc.i++
    return { kind: 'array', items }
  }
  while (true) {
    if (sc.atEnd()) sc.err('unterminated array')
    const value = parseValue(sc, prefixPath.concat([items.length]))
    items.push(value)
    sc.skipWS()
    if (sc.atEnd()) sc.err('unterminated array')
    const c = sc.s[sc.i]
    if (c === ',') {
      sc.i++
      sc.skipWS()
      if (sc.peek() === ']') {
        sc.i++
        return { kind: 'array', items }
      }
      continue
    }
    if (c === ']') {
      sc.i++
      return { kind: 'array', items }
    }
    sc.err('unterminated array')
  }
}

function walkIntermediate(table, names, sc, prefixPath) {
  let cur = table
  for (let idx = 0; idx < names.length - 1; idx++) {
    const name = names[idx]
    if (!cur.map.has(name)) {
      const t = makeTable()
      cur.map.set(name, t)
      cur = t
    } else {
      const existing = cur.map.get(name)
      if (existing.kind === 'table') {
        cur = existing
      } else if (existing.kind === 'aot') {
        cur = existing.tables[existing.tables.length - 1]
      } else {
        sc.err(`${formatPath(prefixPath.concat(names.slice(0, idx + 1)))} is not a table`)
      }
    }
  }
  return cur
}

function assignDotted(table, names, valueNode, sc, prefixPath) {
  const cur = walkIntermediate(table, names, sc, prefixPath)
  const lastName = names[names.length - 1]
  if (cur.map.has(lastName)) sc.err(`key ${formatPath(prefixPath.concat(names))} is defined twice`)
  cur.map.set(lastName, valueNode)
}

function parseInlineTable(sc, prefixPath) {
  sc.i++ // consume {
  const table = makeTable()
  sc.skipWS()
  if (sc.peek() === '}') {
    sc.i++
    return table
  }
  while (true) {
    sc.skipWS()
    if (sc.atEnd()) sc.err('unterminated inline table')
    const names = parseDottedName(sc)
    sc.skipWS()
    if (sc.peek() !== '=') {
      if (sc.atEnd()) sc.err('unterminated inline table')
      sc.err('expected = in an inline table')
    }
    sc.i++ // consume =
    const value = parseValue(sc, prefixPath.concat(names))
    assignDotted(table, names, value, sc, prefixPath)
    sc.skipWS()
    if (sc.atEnd()) sc.err('unterminated inline table')
    const c = sc.s[sc.i]
    if (c === ',') {
      sc.i++
      continue
    }
    if (c === '}') {
      sc.i++
      return table
    }
    sc.err('unterminated inline table')
  }
}

function parseHeaderLine(sc, root, state) {
  sc.i++ // consume [
  let isArray = false
  if (sc.peek() === '[') {
    isArray = true
    sc.i++
  }
  const names = parseDottedName(sc)
  sc.skipWS()
  if (sc.peek() !== ']') sc.err('unterminated table header')
  sc.i++
  if (isArray) {
    if (sc.peek() !== ']') sc.err('unterminated table header')
    sc.i++
  }
  sc.skipWS()
  if (!sc.atEnd()) sc.err('trailing text after a table header')

  const cur = walkIntermediate(root, names, sc, [])
  const lastName = names[names.length - 1]
  const fullPath = formatPath(names)

  if (!isArray) {
    if (!cur.map.has(lastName)) {
      const t = makeTable()
      t.headerDefined = true
      cur.map.set(lastName, t)
      state.current = t
      state.currentPath = names.slice()
    } else {
      const existing = cur.map.get(lastName)
      if (existing.kind !== 'table') sc.err(`${fullPath} is not a table`)
      if (existing.headerDefined) sc.err(`table ${fullPath} is defined twice`)
      existing.headerDefined = true
      state.current = existing
      state.currentPath = names.slice()
    }
  } else {
    let aot
    if (!cur.map.has(lastName)) {
      aot = { kind: 'aot', tables: [] }
      cur.map.set(lastName, aot)
    } else {
      aot = cur.map.get(lastName)
      if (aot.kind !== 'aot') sc.err(`${fullPath} is not an array of tables`)
    }
    const t = makeTable()
    t.headerDefined = true
    aot.tables.push(t)
    state.current = t
    state.currentPath = names.slice(0, names.length - 1).concat([lastName, aot.tables.length - 1])
  }
}

function parseKeyValueLine(sc, state) {
  const names = parseDottedName(sc)
  sc.skipWS()
  if (sc.peek() !== '=') sc.err('expected key = value')
  sc.i++ // consume =
  const value = parseValue(sc, state.currentPath.concat(names))
  assignDotted(state.current, names, value, sc, state.currentPath)
  sc.skipWS()
  if (!sc.atEnd()) sc.err('trailing text after a value')
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable()
  const state = { current: root, currentPath: [] }

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]

    let j = 0
    while (j < line.length && (line[j] === ' ' || line[j] === '\t')) j++
    if (j >= line.length || line[j] === '#' || line[j] === ';') continue

    const sc = new LineScanner(line, lineNo)
    sc.i = j
    if (line[j] === '[') parseHeaderLine(sc, root, state)
    else parseKeyValueLine(sc, state)
  }

  return root
}
