{"file_path":"src/format.js","content":"/**
 * Renders a parsed document tree (see src/parser.js) as canonical JSON or as
 * a flat key listing.
 */

function codePoints(s) {
  return Array.from(s, (c) => c.codePointAt(0))
}

function compareByCodePoint(a, b) {
  const ca = codePoints(a)
  const cb = codePoints(b)
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    if (ca[i] !== cb[i]) return ca[i] - cb[i]
  }
  return ca.length - cb.length
}

function sortedKeys(table) {
  return [...table.map.keys()].sort(compareByCodePoint)
}

function jsonValue(node, indent) {
  const pad = '  '.repeat(indent)
  const padChild = '  '.repeat(indent + 1)
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const parts = keys.map((k) => `${padChild}${JSON.stringify(k)}: ${jsonValue(node.map.get(k), indent + 1)}`)
      return `{\n${parts.join(',\n')}\n${pad}}`
    }
    case 'aot': {
      if (node.tables.length === 0) return '[]'
      const parts = node.tables.map((t) => `${padChild}${jsonValue(t, indent + 1)}`)
      return `[\n${parts.join(',\n')}\n${pad}]`
    }
    case 'array': {
      if (node.items.length === 0) return '[]'
      const parts = node.items.map((it) => `${padChild}${jsonValue(it, indent + 1)}`)
      return `[\n${parts.join(',\n')}\n${pad}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toJson(root) {
  return `${jsonValue(root, 0)}\n`
}

function typeName(node) {
  switch (node.kind) {
    case 'table': return 'table'
    case 'aot': return 'array'
    case 'array': return 'array'
    default: return node.kind
  }
}

function walkKeys(node, path, out) {
  out.push(`${path} ${typeName(node)}`)
  if (node.kind === 'table') {
    for (const k of sortedKeys(node)) walkKeys(node.map.get(k), path.length ? `${path}.${k}` : k, out)
  } else if (node.kind === 'aot') {
    node.tables.forEach((t, i) => walkKeys(t, `${path}[${i}]`, out))
  } else if (node.kind === 'array') {
    node.items.forEach((it, i) => walkKeys(it, `${path}[${i}]`, out))
  }
}

export function toKeys(root) {
  const out = []
  for (const k of sortedKeys(root)) walkKeys(root.map.get(k), k, out)
  return out.length ? `${out.join('\n')}\n` : ''
}
